  ('eu-bref-lvic-aaf-2007', 'Reference Document on Best Available Techniques for the Manufacture of Large Volume Inorganic Chemicals: Ammonia, Acids and Fertilisers (LVIC-AAF BREF)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/large-volume-inorganic-chemicals-ammonia-acids-and-fertilisers', '2026-11-26', 'sha256:a7c0fd7b6b6df630910ccefa7cd00bafdc5023f3046a5b667209022d8cedce84', NULL, 'Referencia internacional de ingeniería de procesos para reformado de gas natural (SMR), conversión de CO, síntesis Haber-Bosch (100-250 bar, 400-500 °C), síntesis de urea (140-180 bar, 180-210 °C), stripping y reciclo de carbamato.'),
  ('epa-ap42-ch8-inorganic', 'AP-42 Compilation of Air Pollutant Emissions Factors (Vol. I, Cap. 8: Inorganic Chemical Industry, 8.1 Synthetic Ammonia & 8.2 Urea)', 'U.S. Environmental Protection Agency (US EPA)', 'tecnica', 'https://www.epa.gov/air-emissions-factors-and-quantification/ap-42-fifth-edition-volume-i-chapter-8-inorganic-chemical-0', '2026-11-26', 'sha256:01dd66c7d2f7bdae219eb0cf1041d13552afa9efef1d7e3697f2e67a21a5cd62', NULL, 'Diagramas de flujo de proceso (PFD) y puntos de emisión de plantas integradas de amoníaco sintético, concentración al vacío y granulación de urea.'),
  ('inti-argentina-portal', 'Instituto Nacional de Tecnología Industrial (INTI): asistencia en química, polímeros, metrología y efluentes industriales', 'INTI · Secretaría de Industria y Comercio de la Nación', 'oficial', 'https://www.argentina.gob.ar/inti', '2026-11-26', 'sha256:71af49965c73a89292d2bff7be43077b91572905d0cfbb18c9ee78981a0b7a0a', NULL, 'Referente técnico nacional en caracterización de polietilenos, metrología industrial y control ambiental de complejos químicos en Argentina.'),
  ('eu-bref-nfm-2017', 'Best Available Techniques (BAT) Reference Document for the Non-Ferrous Metals Industries (NFM BREF)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/non-ferrous-metals-industries', '2026-11-26', 'sha256:8baa3084a6a932b26732bd1ceda6c461278a6a5ed0b3afb667580c6600ca03a0', NULL, 'Referencia internacional para aluminio primario Hall-Héroult (ánodos precocidos), hornos de cocción de ánodos y centros de tratamiento seco de gases GTC con adsorción en alúmina y filtros de mangas.'),
  ('epa-ap42-ch9-oil', 'AP-42 Section 9.11.1 Vegetable Oil Processing (Solvent Extraction, Desolventizer-Toaster & Distillation)', 'U.S. Environmental Protection Agency (US EPA)', 'tecnica', 'https://www.epa.gov/sites/default/files/2020-10/documents/c9s11-1.pdf', '2026-11-26', 'sha256:8ccdc7a75267e53bc9a54b7c2f59f75f892dfe8cfebf417ac55dc73387aa4ec0', NULL, 'Diagrama de flujo estándar y balance de extracción de aceite vegetal por solvente hexano, desolventizado-tostado de harina, destilación de miscela y absorbedores de aceite mineral.'),
  ('afdc-biodiesel-doe', 'Biodiesel Production and Distribution (Transesterification, Methanol Recovery & Glycerin Refining)', 'U.S. Department of Energy (AFDC / NREL)', 'tecnica', 'https://afdc.energy.gov/fuels/biodiesel-production', '2026-11-26', 'sha256:2ae2b1ba2f7d7c10eb947fe62586b2ddd6ae57f5bef2db1f25a7c22e63a310fd', NULL, 'Proceso continuo de transesterificación catalítica con metanol, separación FAME/glicerina, recuperación de metanol en exceso y secado al vacío de biodiésel.'),
  ('eu-bref-textiles-2023', 'Best Available Techniques (BAT) Reference Document for the Textiles Industry (TXT BREF)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/textiles-industry', '2026-11-26', 'sha256:95a85ff34aed08721925bc5918789d8422a4790da67db399cd5da328305b5491', NULL, 'Referencia BAT internacional para pretratamiento químico de algodón: descrudado alcalino con NaOH, blanqueo con peróxido de hidrógeno (H2O2) libre de cloro y recuperación de soda.'),
  ('eu-bref-chlor-alkali', 'Best Available Techniques (BAT) Reference Document for the Production of Chlor-alkali (CAK BREF)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/production-chlor-alkali', '2026-11-26', 'sha256:667074387e3bc69d4cc90e4073db5ff2464f97d4772284475e821d6ee9c2c459', NULL, 'Consumo eléctrico BAT en celdas de membrana (2,5-3,0 MWh DC / t Cl2 o ECU = 1 t Cl2 + 1,1 t NaOH + 0,03 t H2) y concentración de soda cáustica al 50%.')
