INSERT INTO public.procesos (proceso_id, producto_id, nombre, ruta_tecnologica, reaccion_global, energia_especifica_valor, energia_especifica_estado, energia_especifica_unidad, descripcion, anio, fuente_id, cita_ubicacion, confianza) VALUES
  ('aluminio-hall-heroult', 'aluminio', 'Producción de aluminio primario (Hall-Héroult)', 'Alúmina calcinada importada (proceso Bayer en origen) + ánodos precocidos de carbono -> reducción electrolítica en criolita fundida -> fundición y solidificación', '2 Al2O3 + 3 C -> 4 Al + 3 CO2', 14.2, 'dato', 'MWh/t Al', 'Cadena completa en Puerto Madryn (Chubut): 6.324.443 MWh consumidos en electrólisis para 445.327 t de aluminio líquido (14,20 MWh/t Al en electrólisis; 15,06 MWh/t Al considerando toda la planta) durante el ejercicio finalizado el 30/06/2025.', 2025, 'aluar-eeff-2025', 'Memoria 2025 pág. 3 (6.324.443 MWh electrólisis / 445.327 t aluminio líquido)', 'alta'),
  ('litio-salmuera-carbonatacion', 'litio', 'Extracción de salmueras y precipitación de carbonato de litio', 'Bombeo de salmuera de salar -> evaporación solar -> purificación (Mg/Ca/B) -> carbonatación con Na2CO3 -> secado y grado batería', '2 LiCl + Na2CO3 -> Li2CO3 + 2 NaCl', NULL, 'sin_datos', 'MWh/t LCE', 'Ruta evaporítica predominante en los salares de altura de la Puna argentina (Jujuy, Catamarca y Salta). El carbonato de litio (Li2CO3) contiene 18,79% de litio en masa (1 t Li equivale a 5,323 t LCE).', 2026, 'riotinto-olaroz-2026', 'riotinto.com/en/operations/south-america/olaroz y USGS MCS 2025 pág. 110', 'alta'),
  ('urea-haber-bosch-sintesis', 'urea', 'Síntesis integrada de amoníaco (Haber-Bosch) y urea granulada', 'Gas natural (CH4) + vapor de agua -> reformado catalítico (H2 + CO2) -> síntesis de amoníaco (N2 + 3 H2) -> carbamato y urea -> granulación', '2 NH3 + CO2 -> CO(NH2)2 + H2O', 17.46, 'dato', 'GJ/t urea', 'Complejo integrado en Ingeniero White (Bahía Blanca). La energía específica de referencia para amoníaco por reformado moderno de gas natural es 30,2 GJ/t NH3 (IPCC Table 3.1), lo que equivale a 17,46 GJ/t urea (4,85 MWh/t) para el consumo real medido en Profertil 2024 (0,578 t NH3/t urea).', 2006, 'ipcc-2006-v3-ch3-amoniaco-urea', 'IPCC 2006 Vol. 3 Cap. 3.2 pág. 3.11 y Table 3.1 pág. 3.15 (30,2 GJ/t NH3)', 'alta'),
  ('algodon-desmote-refinacion-celulosa', 'algodon', 'Desmote industrial y refinación química de fibra de celulosa', 'Algodón en bruto -> secado y prelimpieza -> desmote mecánico (fibra y semilla) -> descrudado alcalino y blanqueo (H2O2) -> hilatura y despacho', '2 H2O2 -> 2 H2O + O2', NULL, 'sin_datos', 'MWh/t fibra', 'Transformación industrial del algodón en bruto cosechado en Chaco y NEA. Cada 3,0 t de algodón en bruto rinden ~1,0 t de fibra de celulosa ((C6H10O5)n), 1,7 t de semilla oleaginosa y 0,3 t de impurezas vegetales.', 2026, 'buyatti-web-2026', 'buyatti.com.ar (desmote y procesamiento de semilla de algodón, Las Breñas, Chaco)', 'alta'),
  ('soja-molienda-extraccion-solvente', 'soja', 'Molienda de soja y extracción continua por solvente (hexano)', 'Limpieza y laminado de poroto -> extracción líquido-sólido con hexano (C6H14) -> desolventizado-tostado de harina -> destilación de miscela y reciclo de hexano -> desgomado de aceite y lecitina', 'C18H34O2 + NaOH -> C18H33NaO2 + H2O', NULL, 'sin_datos', 'MWh/t soja', 'Proceso industrial del nodo oleaginoso Up-River (San Lorenzo, Timbúes y Rosario). Cada tonelada de poroto procesada rinde ~0,76 t de harina proteica (HS 2304.00) y ~0,19 t de aceite crudo (HS 1507.10), con recuperación cerrada del solvente hexano.', 2026, 'renova-web-2026', 'renova.com.ar (Planta Timbúes 32.400 t/día molienda; Planta San Lorenzo 1.450 t/día biodiésel)', 'alta'),
  ('petroquimica-steam-cracking-polietileno', 'petroquimica', 'Craqueo con vapor de etano (Steam Cracking) y polimerización a polietileno', 'Fraccionamiento de gas natural (etano C2H6) -> craqueo térmico con vapor (800-850 °C) -> enfriamiento y destilación criogénica -> polimerización catalítica a polietileno -> extrusión y peletizado', 'C2H6 -> C2H4 + H2', NULL, 'sin_datos', 'GJ/t C2H4', 'Ruta petroquímica gas-intensiva característica del Polo Bahía Blanca. Según IPCC 2006 (Cap. 3.9 Table 3.25), el craqueo de etano rinde 803 kg de etileno por tonelada de carga (1,245 t C2H6/t C2H4) y genera 0,95 t CO2/t C2H4 (Table 3.14).', 2006, 'ipcc-2006-v3-ch3-amoniaco-urea', 'IPCC 2006 Vol. 3 Cap. 3.9 Box 3.9 pág. 3.59, Table 3.14 pág. 3.75 y Table 3.25 pág. 3.82', 'alta'),
  ('biodiesel-transesterificacion-soja', 'biodiesel', 'Transesterificación alcalina de aceite de soja a biodiésel (FAME)', 'Refinación de aceite de soja -> transesterificación catalítica con metanol (CH4O) -> decantación y refinación de glicerina -> recuperación de metanol -> lavado y secado B100', 'C57H104O6 + 3 CH4O -> 3 C19H36O2 + C3H8O3', NULL, 'sin_datos', 'MWh/t biodiésel', 'Síntesis continua de ésteres metílicos de ácidos grasos (FAME) a partir de aceite de soja en el cordón San Lorenzo / Rosario. Estequiometría exacta (base trioleína): 0,9955 t aceite + 0,1081 t metanol -> 1,000 t FAME + 0,1035 t glicerina.', 2026, 'renova-web-2026', 'renova.com.ar (Planta Timbúes 32.400 t/día molienda; Planta San Lorenzo 1.450 t/día biodiésel)', 'alta'),
  ('litio-dle-adsorcion', 'litio', 'Extracción Directa de Litio (DLE) por adsorción y carbonatación (Fénix / Rincón)', 'Salmuera de salar -> adsorción selectiva DLE (horas) -> elución con agua fresca y retorno de salmuera agotada -> purificación IX + concentración -> carbonatación Na2CO3', '2 LiCl + Na2CO3 -> Li2CO3 + 2 NaCl', NULL, 'sin_datos', 'MWh/t LCE', 'Ruta tecnológica activa en Catamarca (Fénix, Salar del Hombre Muerto desde 1997) y Salta (Rincón, 3.000 t/año inicial + expansión 60 ktpa). Captura LiCl selectivamente en columnas/lechos de adsorción sin esperar 12-18 meses de piletas solares.', 2026, 'riotinto-fenix-2026', 'riotinto.com/en/operations/south-america/fenix (DLE adsorption technology since 1997)', 'alta'),
  ('petroquimica-cloro-alcali-pvc', 'petroquimica', 'Proceso Cloro-Álcali (celda de membrana) y cadena vinílica EDC -> MVC -> PVC (Unipar)', 'Salmuera NaCl saturada + electricidad -> celdas de membrana (Cl2 + NaOH + H2) -> cloración de etileno (EDC) y pirólisis a MVC -> polimerización a PVC', '2 NaCl + 2 H2O -> Cl2 + 2 NaOH + H2', 2.5, 'dato', 'MWh/t Cl2 (ECU)', 'Ruta cloro-vinílica operada por Unipar Indupa en el Polo Petroquímico Bahía Blanca. Según EU CAK BREF, una Unidad Electroquímica (ECU) produce 1 t Cl2, 1,1 t NaOH y 0,03 t H2 consumiendo 2,5-3,0 MWh DC en celdas de membrana libres de mercurio y asbesto.', 2014, 'eu-bref-chlor-alkali', 'EU CAK BREF: membrane cell ECU (1 t Cl2 + 1,1 t NaOH + 0,03 t H2, 2,5 MWh DC/t Cl2)', 'alta')
INSERT INTO public.pasos_proceso (paso_id, proceso_id, orden, nombre, tipo_paso, reaccion_balanceada, temperatura_c, presion_bar, reactivos, productos, insumos, subproductos, energia_valor, energia_estado, energia_unidad, descripcion, pos_x, pos_y, anio, fuente_id, cita_ubicacion, confianza) VALUES
  ('al-p1-bayer-origen', 'aluminio-hall-heroult', 1, 'Refinación Bayer en origen (importación)', 'materia_prima', '2 Al(OH)3 -> Al2O3 + 3 H2O', '1000-1100', '1.0', '[{"especie":"Bauxita seca","cantidad":4,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Al2O3 (alúmina calcinada)","cantidad":1.96,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"NaOH (digestión Bayer en origen)","cantidad":null,"unidad":"reciclo"}]'::jsonb, '[{"especie":"Lodo rojo (en país de origen)","cantidad":null,"unidad":"residuo"}]'::jsonb, NULL, 'sin_datos', NULL, 'Argentina no produce bauxita ni alúmina a escala primaria: importa el 100% de la alúmina calcinada (HS 2818.20, 871.523 t en 2024 según UN Comtrade). Regla general USGS: ~4 t de bauxita seca producen ~2 t de alúmina para obtener 1 t de aluminio.', 20, 170, 2025, 'usgs-mcs-2025-bauxita', 'USGS MCS 2025 Bauxite and Alumina pág. 43 nota 1 y UN Comtrade HS 281820 (2024)', 'alta'),
  ('li-p1-bombeo-salmuera', 'litio-salmuera-carbonatacion', 1, 'Bombeo de salmuera continental', 'materia_prima', NULL, '10-20', '0.65', '[{"especie":"Salmuera subterránea con LiCl, NaCl, MgCl2","cantidad":null,"unidad":"m3/t LCE"}]'::jsonb, '[{"especie":"Salmuera cruda hacia piletas","cantidad":null,"unidad":"m3/t LCE"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'MWh/t LCE', 'Extracción por pozos desde acuíferos hipersalinos de la Puna (Salar de Olaroz, Hombre Muerto y Rincón) a ~3.900-4.100 msnm.', 20, 150, 2026, 'riotinto-olaroz-2026', 'riotinto.com/en/operations/south-america/olaroz y USGS MCS 2025 pág. 110', 'alta'),
  ('ur-p1-gas-desulfuracion', 'urea-haber-bosch-sintesis', 1, 'Recepción y desulfuración de gas natural', 'materia_prima', NULL, '350-400', '40', '[{"especie":"CH4 (gas natural de cuenca Neuquina/Austral)","cantidad":0.25,"unidad":"t/t urea"}]'::jsonb, '[{"especie":"CH4 desulfurado","cantidad":0.25,"unidad":"t/t urea"}]'::jsonb, '[{"especie":"Lecho de ZnO (absorción de azufre)","cantidad":null,"unidad":"catalizador"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'GJ/t urea', 'Acondicionamiento y remoción de compuestos azufrados del gas natural (hasta 2.500.000 m3/día en Profertil Bahía Blanca) para proteger los catalizadores de reformado.', 20, 150, 2025, 'profertil-eecc-2025', 'EECC-31-12-25.pdf pág. 4, 6, 78-79 y 88 (Memoria y Reseña Informativa)', 'alta'),
  ('alg-p1-recepcion-limpieza', 'algodon-desmote-refinacion-celulosa', 1, 'Recepción, secado y prelimpieza de algodón en bruto', 'materia_prima', NULL, '60-80', '1.0', '[{"especie":"Algodón en bruto cosechado","cantidad":3,"unidad":"t/t fibra"}]'::jsonb, '[{"especie":"Algodón en bruto seco y limpio","cantidad":2.7,"unidad":"t/t fibra"}]'::jsonb, '[{"especie":"Aire caliente de secado","cantidad":null,"unidad":"servicio térmico"}]'::jsonb, '[{"especie":"Restos vegetales, brácteas y polvo","cantidad":0.3,"unidad":"t/t fibra"}]'::jsonb, NULL, 'sin_datos', 'MWh/t fibra', 'Acondicionamiento de humedad y separación neumática de restos vegetales de cosecha mecánica (stripper/picker) en desmotadoras chaqueñas.', 20, 150, 2025, 'sagyp-estimaciones-2026-03', 'estimaciones-agricolas-2026-03.csv cultivo=Algodón provincia_id=22 campania=2024/2025', 'alta'),
  ('soj-p1-limpieza-laminado', 'soja-molienda-extraccion-solvente', 1, 'Limpieza, quebrado, descascarado y laminado', 'materia_prima', NULL, '60-65', '1.0', '[{"especie":"Poroto de soja (Glycine max)","cantidad":1,"unidad":"t/t soja"}]'::jsonb, '[{"especie":"Láminas acondicionadas de soja","cantidad":0.97,"unidad":"t/t soja"}]'::jsonb, '[{"especie":"Vapor de acondicionamiento","cantidad":null,"unidad":"servicio térmico"}]'::jsonb, '[{"especie":"Cáscara (pelletizada) e impurezas","cantidad":0.03,"unidad":"t/t soja"}]'::jsonb, NULL, 'sin_datos', 'MWh/t soja', 'Recepción por camiones y barcazas en puertos del Paraná, descascarado parcial y laminado a 0,3 mm para facilitar la extracción.', 20, 150, 2026, 'renova-web-2026', 'renova.com.ar (Planta Timbúes 32.400 t/día molienda)', 'alta'),
  ('pet-p1-fraccionamiento-etano', 'petroquimica-steam-cracking-polietileno', 1, 'Separación de etano (C2H6) desde gas natural', 'materia_prima', NULL, '-90 a -30', '30', '[{"especie":"C2H6 en líquidos de gas natural (Cuenca Neuquina)","cantidad":1.245,"unidad":"t/t C2H4"}]'::jsonb, '[{"especie":"C2H6 (etano grado petroquímico)","cantidad":1.245,"unidad":"t/t C2H4"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'GJ/t C2H4', 'Fraccionamiento criogénico en General Cerri / Puerto Galván (Bahía Blanca) que provee etano por ducto directo a los crackers de etileno.', 20, 150, 2006, 'ipcc-2006-v3-ch3-amoniaco-urea', 'IPCC 2006 Vol. 3 Cap. 3.9 Table 3.25 pág. 3.82', 'alta'),
